import { checkInsight } from './wireframe-insight.js';
const mk = (t, o = {}) => ({ t, ...o });
const kids = (children) => [children].flat(Infinity).filter(Boolean);
export const col = (c, o) => mk('col', { ...o, children: kids(c) });
export const row = (c, o) => mk('row', { ...o, children: kids(c) });
export const card = (c, o) => mk('card', { ...o, children: kids(c) });
export const spacer = (h = 8, o) => mk('spacer', { h, ...o });
export const text = (text, o) => mk('text', { ...o, text });
export const btn = (label, o) => mk('btn', { ...o, label });
export const input = (label, o) => mk('input', { ...o, label });
export const select = (label, o) => mk('select', { ...o, label });
export const chip = (label, o) => mk('chip', { ...o, label });
export const tabs = (labels, o) => mk('tabs', { ...o, labels });
export const appbar = (title, o) => mk('appbar', { ...o, title });
export const seek = (o) => mk('seek', o);
export const kv = (pairs, o) => mk('kv', { ...o, pairs });
export const stat = (value, label, o) => mk('stat', { ...o, value: String(value), label });
export const list = (items, o) => mk('list', { ...o, items });
export const table = (columns, rows, o) => mk('table', { ...o, columns, rows });
export const alert = (text, o) => mk('alert', { ...o, text });
export const map = (o) => mk('map', o);
export const video = (o) => mk('video', o);
export const heat = (o) => mk('heat', o);
export const pointcloud = (o) => mk('pointcloud', o);
export const chart = (o) => mk('chart', o);
export const image = (label, o) => mk('image', { ...o, label });
export const dialog = (title, o) => mk('dialog', { ...o, title });
export const toast = (text, o) => mk('toast', { ...o, text });
export const fusion = (o) => mk('fusion', o);
export const compare = (o) => mk('compare', o);
export const region = (label, o) => mk('region', { ...o, label });
export const robot = (o) => mk('robot', o);
export const battery = (level, o) => mk('battery', { ...o, level });
export const signal = (level, o) => mk('signal', { ...o, level });
export const insight = (o) => { checkInsight(o); return mk('insight', o); };
export const breadcrumb = (items, o) => mk('breadcrumb', { ...o, items });
export const toggle = (label, o) => mk('toggle', { ...o, label });
export const checkbox = (label, o) => mk('checkbox', { ...o, label });
export const radio = (label, o) => mk('radio', { ...o, label });
export const slider = (label, o) => mk('slider', { ...o, label });
